--
-- Table structure for table `health_assessment_report`
--

DROP TABLE IF EXISTS `health_assessment_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `health_assessment_report` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `health_assessment_id` bigint unsigned DEFAULT NULL COMMENT '健康评估ID',
  `assessment_time` datetime DEFAULT NULL COMMENT '评估时间',
  `assessor_name` varchar(50) DEFAULT NULL COMMENT '评估员姓名',
  `recommended_room_type` varchar(50) DEFAULT NULL COMMENT '推荐入住房型（如：标准双人间）',
  `recommended_care_level` varchar(20) DEFAULT NULL COMMENT '推荐护理等级（如：一级护理等级）',
  `care_focus` text COMMENT '护理重点（多条用分号分隔，如：血压管控；肢体协助；认知干预）',
  `suggestion_description` text COMMENT '建议说明（如：老人基础健康状况稳定，日常生活能部分自理）',
  `daily_activity_level` varchar(10) DEFAULT NULL COMMENT '日常生活活动等级',
  `mental_status_level` varchar(10) DEFAULT NULL COMMENT '精神状态等级',
  `perception_communication_level` varchar(10) DEFAULT NULL COMMENT '感知觉与沟通等级',
  `social_participation_level` varchar(10) DEFAULT NULL COMMENT '社会参与等级',
  `initial_ability_level` varchar(50) DEFAULT NULL COMMENT '老年人能力初步等级',
  `final_ability_level` varchar(50) DEFAULT NULL COMMENT '老年人能力最终等级',
  `level_change_reason` text COMMENT '等级变更依据说明',
  `family_cooperation` text COMMENT '家属配合事项（多条用分号分隔）',
  `diet_suggestion` text COMMENT '饮食建议（如：低盐低脂饮食，控制主食摄入量，避免高糖食物）',
  `psychological_care` text COMMENT '心理关怀建议（如：多关注老人情绪变化，每日进行不少于10分钟的一对一沟通）',
  `institution_preparation` text COMMENT '机构准备事项（多条用分号分隔，如：提前准备轮椅；房间配置；照护人员适配）',
  `health_score` varchar(20) DEFAULT NULL COMMENT '健康评分',
  `risk_level` varchar(20) DEFAULT NULL COMMENT '严重危险(健康, 提示, 风险, 危险, 严重危险)',
  `report_summary` text COMMENT '报告总结',
  `abnormal_analysis` text COMMENT '异常分析',
  `system_score` varchar(255) DEFAULT NULL COMMENT '健康系统分值',
  `create_by` varchar(255) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(255) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` text COMMENT '备注',
  `core_suggestion` int DEFAULT NULL COMMENT '核心建议，0-不建议入住，1-建议入住',
  `check_in_status` tinyint DEFAULT NULL COMMENT '入住状态：0-未入住，1-已入住',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='健康评估报告表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `health_assessment_report`
--

LOCK TABLES `health_assessment_report` WRITE;
/*!40000 ALTER TABLE `health_assessment_report` DISABLE KEYS */;
INSERT INTO `health_assessment_report` VALUES (3,10,'2026-04-01 17:30:46','admin',NULL,NULL,NULL,NULL,'能力完好','轻度受损','能力完好','能力完好','能力完好','能力完好','',NULL,NULL,NULL,NULL,'72.5','风险','体检报告中发现心率偏快伴偶发早搏、轻度脂肪肝、慢性胆囊炎可能、脾脏轻度增大、右肾小囊肿、前列腺形态略增大、牙周炎及牙龈退缩共7项异常指标。综合这些临床指标和数据分析：循环系统存在‘高危’风险；消化系统存在‘中危’风险；泌尿系统和感官系统存在‘低危’风险；呼吸系统、免疫系统、运动系统基本健康。建议针对上述异常指标采取相应干预措施，并定期复查以监测健康状况。','[{\"conclusion\":\"心率偏快伴偶发早搏\",\"examinationItem\":\"心率\",\"result\":\"92\",\"referenceValue\":\"<100\",\"unit\":\"次/分\",\"interpret\":\"心率偏快可能与年龄、压力、睡眠不足或潜在心血管问题有关，偶发早搏提示可能存在轻微心律失常。\",\"advice\":\"建议减少咖啡因摄入，避免过度劳累，定期复查心电图，必要时咨询心脏科医生进行动态心电图检查。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"脂肪肝通常与高脂饮食、缺乏运动、肥胖等因素相关，长期未控制可能导致肝功能异常。\",\"advice\":\"调整饮食结构，减少高脂肪、高糖食物摄入，增加有氧运动如快走或游泳，每3-6个月复查一次肝功能和B超。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"慢性胆囊炎多由胆结石或长期不良饮食习惯引起，可能出现右上腹隐痛或消化不良症状。\",\"advice\":\"避免油腻食物，规律进餐，定期复查胆囊B超，若症状明显需进一步诊治。\"},{\"conclusion\":\"脾脏轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"脾脏增大可能与感染、血液病或肝脏疾病相关，需结合其他指标综合判断。\",\"advice\":\"建议监测脾脏变化，排查血液系统疾病及肝脏疾病，定期复查腹部B超。\"},{\"conclusion\":\"右肾小囊肿可能\",\"examinationItem\":\"肾脏B超\",\"result\":\"右肾下极见一大小约5mm的无回声区\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"小囊肿一般为良性病变，但需定期观察其大小变化以排除恶性可能。\",\"advice\":\"每6-12个月复查肾脏B超，无需特殊处理，注意保持良好生活习惯。\"},{\"conclusion\":\"前列腺形态略增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"前列腺增大常见于老年男性，可能与前列腺增生或炎症有关，需警惕前列腺癌风险。\",\"advice\":\"建议进行前列腺特异性抗原（PSA）检测，如有排尿困难等症状及时就医。\"},{\"conclusion\":\"牙周炎及牙龈退缩\",\"examinationItem\":\"口腔科检查\",\"result\":\"牙周炎，牙龈退缩\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"牙周炎与口腔卫生不良、吸烟等有关，长期不治疗可能导致牙齿松动甚至脱落。\",\"advice\":\"加强口腔清洁，使用软毛牙刷，定期洗牙，戒烟限酒，必要时接受牙周治疗。\"}]','{\"breathingSystem\":95,\"digestiveSystem\":68,\"endocrineSystem\":75,\"immuneSystem\":85,\"circulatorySystem\":65,\"urinarySystem\":80,\"motionSystem\":90,\"senseSystem\":70}','1','2026-04-01 17:30:46',NULL,NULL,NULL,1,0),(4,11,'2026-04-02 12:00:45','admin',NULL,NULL,NULL,NULL,'能力完好','能力完好','能力完好','能力完好','能力完好','能力完好','',NULL,NULL,NULL,NULL,'72.5','风险','体检报告显示心率、肝脏B超、胆囊B超、脾脏B超、肾脏B超、前列腺B超、听力测试、口腔检查共8项指标提示异常，其中心率、脾脏增大及前列腺形态异常存在较高风险；血脂、血糖、血常规、尿常规等30余项指标提示正常。综合这些临床指标和数据分析：循环系统、消化系统和泌尿生殖系统存在一定隐患，其中循环系统有“高危”风险；消化系统有“中危”风险；泌尿生殖系统有“低危”风险。建议针对上述异常项目采取相应干预措施，定期随访监测健康状况。','[{\"conclusion\":\"心率略快伴偶发早搏\",\"examinationItem\":\"心率\",\"result\":\"92次/分\",\"referenceValue\":\"<100次/分\",\"unit\":\"次/分\",\"interpret\":\"心率略快可能与年龄、压力、睡眠不足或潜在的心脏问题有关。偶发早搏提示可能存在心脏节律异常，需进一步评估是否存在心血管疾病风险。\",\"advice\":\"建议进行动态心电图监测以明确早搏频率和类型，同时减少咖啡因摄入，避免过度劳累。定期复查血压和心率，并在必要时咨询心脏科医生。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"脂肪肝通常与高脂饮食、肥胖、饮酒或代谢综合征相关，若不及时干预可能发展为脂肪性肝炎甚至肝硬化。\",\"advice\":\"调整饮食结构，减少油脂和糖分摄入，多吃蔬菜水果，增加有氧运动如快走、游泳等，每餐控制总热量。每年复查一次肝功能及B超。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙\",\"referenceValue\":\"光滑\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙常提示慢性炎症，可能与长期高脂肪饮食、胆汁淤积或感染有关，严重时可能导致胆结石形成。\",\"advice\":\"清淡饮食，避免油炸食品和动物内脏，规律进餐，保持适量饮水。如有右上腹疼痛或不适，应及时就医。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大\",\"referenceValue\":\"正常大小\",\"unit\":\"-\",\"interpret\":\"脾脏轻度增大可能由感染、血液病或其他全身性疾病引起，需要排除恶性肿瘤或其他系统性疾病的可能性。\",\"advice\":\"建议进一步检查血常规、腹部CT或MRI，同时观察是否有乏力、贫血等症状。定期随访脾脏变化情况。\"},{\"conclusion\":\"右肾小囊肿可能\",\"examinationItem\":\"肾脏B超\",\"result\":\"右肾下极见一大小约5mm的无回声区\",\"referenceValue\":\"无囊肿\",\"unit\":\"-\",\"interpret\":\"单纯性肾囊肿多为良性，但需警惕其增长速度及是否影响肾功能。\",\"advice\":\"无需特殊治疗，但应每年复查一次B超，监测囊肿大小变化。如果出现腰痛或血尿，立即就诊。\"},{\"conclusion\":\"前列腺形态略增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"正常形态\",\"unit\":\"-\",\"interpret\":\"前列腺增生常见于老年男性，可能伴随排尿困难、夜尿增多等症状，需排除前列腺癌的可能性。\",\"advice\":\"建议检测前列腺特异性抗原（PSA），并根据结果决定是否行进一步检查。日常注意保暖，避免久坐，适当锻炼盆底肌肉。\"},{\"conclusion\":\"左耳听力轻度下降\",\"examinationItem\":\"听力测试\",\"result\":\"轻度下降\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"老年人听力下降可能与自然衰老、噪音暴露、耳部疾病或血液循环障碍有关。\",\"advice\":\"避免长时间佩戴耳机，远离噪声环境，定期复查听力。必要时可考虑助听器辅助改善生活质量。\"},{\"conclusion\":\"牙周炎及牙龈退缩\",\"examinationItem\":\"口腔检查\",\"result\":\"牙周炎，牙龈退缩\",\"referenceValue\":\"无牙周病\",\"unit\":\"-\",\"interpret\":\"牙周炎是细菌感染引起的慢性炎症，与口腔卫生不良密切相关，严重时会导致牙齿松动甚至脱落。\",\"advice\":\"加强口腔清洁，使用软毛牙刷，每天至少刷牙两次，配合使用牙线和漱口水。尽快到口腔科进行洁治和刮治治疗。\"}]','{\"breathingSystem\":90,\"digestiveSystem\":68,\"endocrineSystem\":75,\"immuneSystem\":85,\"circulatorySystem\":65,\"urinarySystem\":70,\"motionSystem\":88,\"senseSystem\":60}','1','2026-04-02 12:00:45',NULL,NULL,NULL,1,0),(5,12,'2026-04-02 12:07:20','admin',NULL,NULL,NULL,NULL,'能力完好','能力完好','能力完好','能力完好','能力完好','能力完好','',NULL,NULL,NULL,NULL,'72.5','风险','体检报告中心率、肝脏B超、胆囊B超、脾脏B超、前列腺B超、视力共6项指标提示异常，其中心血管系统存在‘高危’风险，主要表现为心率偏快伴偶发早搏；泌尿系统和消化系统分别存在‘中危’和‘低危’风险，包括前列腺形态增大和慢性胆囊炎可能；感官系统评分较低，主要受视力下降影响。综合来看，需重点关注心血管健康，并对肝脏、胆囊、前列腺等问题进行随访管理。','[{\"conclusion\":\"心率偏快伴偶发早搏\",\"examinationItem\":\"心率\",\"result\":\"92次/分\",\"referenceValue\":\"<100次/分\",\"unit\":\"次/分\",\"interpret\":\"心率略高于正常范围，伴有偶发早搏，可能提示心脏功能存在轻度异常或循环系统问题。长期心率过快可能导致心脏负担加重，需警惕潜在的心血管疾病风险。\",\"advice\":\"建议进行24小时动态心电图检查以明确早搏频率和类型；减少咖啡因、酒精摄入，避免过度劳累；定期监测血压和心率变化；必要时至心内科就诊评估是否需要药物干预。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"肝脏B超显示实质回声略粗糙，提示可能存在轻度脂肪肝，与饮食结构不合理、缺乏运动等因素相关，长期发展可能增加肝硬化或代谢性疾病的风险。\",\"advice\":\"建议低脂、低糖、高纤维饮食，控制总热量摄入；每周至少进行150分钟中等强度有氧运动（如快走、游泳）；3-6个月后复查肝功能及B超；避免饮酒。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙提示可能存在慢性胆囊炎，通常与胆汁淤积、饮食不规律或高脂饮食有关，严重时可引发急性胆囊炎或胆结石。\",\"advice\":\"建议清淡饮食，避免油腻食物及暴饮暴食；如有右上腹不适症状，应及时就医；必要时复查腹部B超并咨询消化科医生。\"},{\"conclusion\":\"脾脏轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"脾脏轻度增大可能由感染、血液病或其他全身性疾病引起，需进一步排查是否存在潜在病因。\",\"advice\":\"建议结合血常规及其他相关检查明确原因；保持良好的生活习惯，增强免疫力；若出现乏力、发热等症状，及时复诊。\"},{\"conclusion\":\"前列腺形态略增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"前列腺形态增大可能提示良性前列腺增生，常见于老年男性，但需排除恶性病变的可能性。\",\"advice\":\"建议检测前列腺特异性抗原（PSA），必要时行直肠指检或MRI检查；多饮水，避免久坐，适量锻炼盆底肌肉；如排尿困难明显，应至泌尿外科就诊。\"},{\"conclusion\":\"视力下降\",\"examinationItem\":\"视力\",\"result\":\"左眼0.3，右眼0.4\",\"referenceValue\":\"≥1.0\",\"unit\":\"-\",\"interpret\":\"双眼视力下降符合老视特征，可能影响日常生活质量，尤其是阅读和近距离工作。\",\"advice\":\"建议佩戴合适的老花镜矫正视力；注意用眼卫生，避免长时间近距离用眼；每年复查一次视力。\"}]','{\"breathingSystem\":90,\"digestiveSystem\":75,\"endocrineSystem\":80,\"immuneSystem\":85,\"circulatorySystem\":65,\"urinarySystem\":70,\"motionSystem\":95,\"senseSystem\":60}','1','2026-04-02 12:07:20',NULL,NULL,NULL,1,0),(6,13,'2026-04-02 12:09:57','admin',NULL,NULL,NULL,NULL,'能力完好','能力完好','能力完好','能力完好','能力完好','能力完好','',NULL,NULL,NULL,NULL,'72.5','风险','体检报告显示心率、视力、肝脏、胆囊、脾脏、肾脏、前列腺等多项指标存在异常，其中心率略快伴偶发早搏、轻度脂肪肝、慢性胆囊炎可能性较大，提示循环系统和消化系统存在一定隐患；右肾小囊肿及前列腺形态增大则需密切随访。综合分析：心脑血管系统有“高危”风险；泌尿系统有“中危”风险；消化系统有“低危”风险。建议采取针对性健康管理措施，包括改善生活方式、定期复查及专科随访。','[{\"conclusion\":\"心率略快伴偶发早搏\",\"examinationItem\":\"心率\",\"result\":\"92次/分\",\"referenceValue\":\"<100次/分\",\"unit\":\"次/分\",\"interpret\":\"心率略高于正常范围，伴有偶发早搏，提示可能存在心脏功能异常或循环系统问题。可能与年龄、压力、睡眠不足、饮食中盐分摄入过多等有关。\",\"advice\":\"建议定期监测心率及血压，避免过度劳累和精神紧张，减少高盐食物的摄入。如有持续心悸或胸闷等症状，应及时就医进行心电图和动态心电图检查。\"},{\"conclusion\":\"视力下降（老视）\",\"examinationItem\":\"视力左/右\",\"result\":\"左眼0.3，右眼0.4\",\"referenceValue\":\"≥1.0\",\"unit\":\"-\",\"interpret\":\"视力下降符合老视特征，属于老年人常见现象，但需关注是否存在其他眼部疾病如白内障或黄斑病变的风险。\",\"advice\":\"建议佩戴合适的老花镜，并定期复查视力。避免长时间用眼，保持良好的阅读习惯，适当补充富含维生素A的食物如胡萝卜、菠菜等。\"},{\"conclusion\":\"轻度脂肪肝\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"肝脏实质回声略粗糙提示可能存在轻度脂肪肝，通常与肥胖、饮酒、高脂饮食或代谢综合征相关。\",\"advice\":\"控制体重，减少油腻食物和酒精摄入，增加膳食纤维，适量运动如快走、游泳等。必要时复查肝功能并咨询消化科医生。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙\",\"referenceValue\":\"光滑\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙提示可能存在慢性胆囊炎，常因长期不良饮食习惯（如高脂肪、高胆固醇饮食）或胆结石引起。\",\"advice\":\"避免油腻、辛辣刺激性食物，规律进餐，少食多餐。若出现右上腹疼痛或消化不良症状，应尽快就医进一步评估。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大\",\"referenceValue\":\"正常大小\",\"unit\":\"-\",\"interpret\":\"脾轻度增大可能与感染、血液病或其他全身性疾病有关，需要进一步排查潜在病因。\",\"advice\":\"建议定期复查脾脏情况，同时结合血常规及其他实验室检查明确原因。如有发热、乏力等症状，应及时就诊。\"},{\"conclusion\":\"右肾小囊肿\",\"examinationItem\":\"肾脏B超\",\"result\":\"右肾下极见一大小约5mm的无回声区\",\"referenceValue\":\"未见异常\",\"unit\":\"-\",\"interpret\":\"右肾小囊肿一般为良性病变，但需定期随访观察其变化，以防囊肿增大或并发感染。\",\"advice\":\"每6-12个月复查一次肾脏B超，注意多饮水，避免憋尿。如出现腰痛、血尿等症状，立即就医。\"},{\"conclusion\":\"前列腺形态略增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"正常形态\",\"unit\":\"-\",\"interpret\":\"前列腺形态增大且回声不均提示可能存在前列腺增生或炎症，需进一步检查以排除恶性病变。\",\"advice\":\"建议检测前列腺特异性抗原（PSA），并根据结果决定是否需要泌尿外科进一步诊治。日常生活中注意避免久坐，保持规律排尿。\"}]','{\"breathingSystem\":90,\"digestiveSystem\":68,\"endocrineSystem\":75,\"immuneSystem\":85,\"circulatorySystem\":65,\"urinarySystem\":80,\"motionSystem\":95,\"senseSystem\":60}','1','2026-04-02 12:09:57',NULL,NULL,NULL,1,0);
/*!40000 ALTER TABLE `health_assessment_report` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `knowledge_base`
--

DROP TABLE IF EXISTS `knowledge_base`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_base` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL COMMENT '知识标题',
  `category` int unsigned NOT NULL COMMENT '分类',
  `tags` varchar(255) DEFAULT NULL COMMENT '标签数组',
  `status` tinyint NOT NULL COMMENT '状态 0-禁用  1-启用',
  `priority` tinyint unsigned NOT NULL DEFAULT '3' COMMENT '优先级(1-5)',
  `document_url` varchar(255) DEFAULT NULL COMMENT '文档访问URL',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` bigint DEFAULT NULL COMMENT '创建人id',
  `update_by` bigint DEFAULT NULL COMMENT '更新人id',
  `remark` text COMMENT '备注',
  PRIMARY KEY (`id`)
