INSERT INTO `nursing_project` VALUES (1,'修剪指甲',1,'次',10.00,'https://itheim.oss-cn-beijing.aliyuncs.com/b6631465-1684-41fe-8ccd-0b027cb91e90.png','根据老人身体状况，定期修剪手指甲、脚趾甲，避免过长、开裂或划伤皮肤。修剪时动作轻柔，仔细打磨边缘，兼顾舒适度与安全性，预防倒刺、嵌甲及感染。去',1,'1','1',NULL,'2024-08-29 16:51:50','2026-03-21 13:04:21'),(2,'衣物清洁',1,'件',5.00,'https://itheim.oss-cn-beijing.aliyuncs.com/41fc58d3-0627-4fa9-8459-906599aa1efa.png','定时收集、分类清洗老人衣物、床单等织物，按材质选择合适洗涤方式。洗净后烘干、熨烫、整理归位，保持衣物干净、整洁、无异味，提升老人穿着舒适度。',1,'1','1',NULL,'2024-08-29 16:52:27','2025-04-27 15:09:00'),(3,'整理床铺',1,'次',15.00,'https://itheim.oss-cn-beijing.aliyuncs.com/e611fcc9-dc45-49ac-abeb-f2ea99c2cffc.png','每日定时整理床铺，更换枕套、床单、被罩，保持床单位平整、干燥、无褶皱。及时清理床上杂物，为老人营造整洁、舒适、卫生的睡眠与休息环境。',1,'1','1',NULL,'2024-08-29 16:52:52','2024-08-29 08:51:46'),(4,'助餐',1,'餐',15.00,'https://itheim.oss-cn-beijing.aliyuncs.com/d91ba642-88e5-4c3d-8e50-a681ae3300e5.png','根据老人饮食需求与身体状况，协助进食、饮水。对行动不便、吞咽困难者，提供喂食、喂水服务，注意温度、速度与营养搭配，确保老人安全、顺利进餐。',1,'1','1',NULL,'2024-08-29 16:53:29','2024-08-29 08:52:24'),(5,'助浴',1,'次',40.00,'https://itheim.oss-cn-beijing.aliyuncs.com/125df948-7646-4fce-b322-1db0a84856e7.png','协助老人完成全身清洁洗浴，做好防滑、保暖与安全防护。根据老人自理能力，全程陪护，控制水温与时间，避免滑倒、受凉，清洁后及时擦干穿衣。',1,'1','1',NULL,'2024-08-29 16:53:51','2024-08-29 08:52:46'),(6,'洗头',1,'次',20.00,'https://itheim.oss-cn-beijing.aliyuncs.com/a38883fc-870b-40ff-a256-54ce2fc17af9.png','定期为老人清洗头发，调节合适水温，做好头部与颈部保暖。冲洗干净后及时擦干、吹干，预防感冒，保持头发清洁清爽，提升老人舒适感。',1,'1','1',NULL,'2024-08-29 16:54:22','2024-08-29 08:53:17'),(7,'洗脸',1,'次',15.00,'https://itheim.oss-cn-beijing.aliyuncs.com/95b0ad37-5d61-4ec2-a961-d6fb691a18f0.png','每日早晚协助老人清洁面部，使用温和用品，轻柔擦拭眼、耳、鼻、面部及颈部。保持面部干净清爽，促进血液循环，提升日常舒适度。',1,'1','1',NULL,'2024-08-29 16:54:45','2024-08-29 08:53:40'),(8,'洗脚',1,'次',20.00,'https://itheim.oss-cn-beijing.aliyuncs.com/8437eb2d-3ea5-4eee-9d78-017bc8b3a66e.png','每日为老人清洁双脚，调节适宜水温，浸泡、清洗、擦干双脚及趾缝。促进足部血液循环，缓解疲劳，预防脚气、干裂，提升睡眠与生活质量。',1,'1','1',NULL,'2024-08-29 16:55:08','2024-08-29 08:54:03'),(20,'全身洗浴',2,'元',90.00,'https://hm-xhzb.oss-cn-beijing.aliyuncs.com/476920d1-1dbd-4205-a1b6-95568881477e.png','北京市海淀区西三旗街北京市海淀区西三旗街北京市海淀区西三旗街北京市海淀区西三旗街北京市',1,'1','1',NULL,'2026-03-09 15:59:52','2026-03-28 16:52:37'),(31,'心理咨询',1,'次',25.00,'https://hm-xhzb.oss-cn-beijing.aliyuncs.com/12b06336-24df-416b-a0ea-eff8f53e6fc1.png','心理咨询心理咨询',1,'1',NULL,NULL,'2026-03-28 17:07:01','2026-03-28 09:07:01'),(32,'护理项目测试',1,'次',10.00,'https://yjy-slwl-oss.oss-cn-hangzhou.aliyuncs.com/ae7cf766-fb7b-49ff-a73c-c86c25f280e1.png','无特殊要求',1,'1',NULL,NULL,'2026-04-06 10:02:14','2026-04-06 02:02:12'),(33,'测试护理项目AI2',1,'次',100.00,'https://img2.baidu.com/it/u=3227619927,365499885&fm=253&fmt=auto&app=120&f=JPEG?w=938&h=500','测试护理项目AI2',1,'1',NULL,'测试护理项目AI2','2026-07-17 16:42:12','2026-07-17 08:42:12');
